template:
trait Pet {
    fn talk(&self) -> &'static str;
}

struct Dog;
struct Cat;

impl Pet for Dog {
    fn talk(&self) -> &'static str { "woof" }
}

impl Pet for Cat {
    fn talk(&self) -> &'static str { "meow" }
}

fn make_pet(is_dog: bool) -> ⟦ret_ty⟧ {
    if is_dog {
        ⟦dog_expr⟧
    } else {
        Box::new(Cat)
    }
}

fn main() {
    let p = make_pet(true);
    println!("{}", p.talk());
}
